[Fact]
public void AC5_GeneratedCodeCompilesCleanAndRoundTrips()
{
    var (compilation, generatedTrees) = this.RunGenerators(UserSource, preprocessorSymbols: new[] { "NET", "NET8_0", "NET8_0_OR_GREATER" });
    var diags = compilation.GetDiagnostics()
        .Where(d => d.Severity >= DiagnosticSeverity.Warning && d.Id != "CS1591")
        .ToList();
    Assert.True(diags.Count == 0, "Diagnostics: " + string.Join(Environment.NewLine, diags));

    using var ms = new MemoryStream();
    var emit = compilation.Emit(ms);
    Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
    ms.Position = 0;
    var alc = new AssemblyLoadContext("probe" + Guid.NewGuid(), isCollectible: true);
    try
    {
        Assembly asm = alc.LoadFromStream(ms);
        var resolverType = asm.GetType("Probe.GenResolver", throwOnError: true)!;
        var generated = (IFormatterResolver)resolverType.GetField("Instance", BindingFlags.Public | BindingFlags.Static)!.GetValue(null)!;
        var options = MessagePackSerializerOptions.Standard.WithResolver(CompositeResolver.Create(generated, StandardResolver.Instance));

        Type intKeyed = asm.GetType("Probe.IntKeyed", true)!;
        object obj = Activator.CreateInstance(intKeyed)!;
        intKeyed.GetProperty("A")!.SetValue(obj, 42);
        intKeyed.GetProperty("B")!.SetValue(obj, "hello");
        intKeyed.GetProperty("E")!.SetValue(obj, Enum.ToObject(asm.GetType("Probe.MyEnum", true)!, 2));
        object ua = Activator.CreateInstance(asm.GetType("Probe.UnionA", true)!)!;
        ua.GetType().GetProperty("V")!.SetValue(ua, 7);
        intKeyed.GetProperty("U")!.SetValue(obj, ua);
        Type genInt = asm.GetType("Probe.Gen`1", true)!.MakeGenericType(typeof(int));
        object g = Activator.CreateInstance(genInt)!;
        genInt.GetProperty("Value")!.SetValue(g, 99);
        intKeyed.GetProperty("G")!.SetValue(obj, g);

        byte[] bytes = MessagePackSerializer.Serialize(intKeyed, obj, options);
        Assert.Equal("[42,\"hello\",2,[0,[7]],[99]]", MessagePackSerializer.ConvertToJson(bytes));
        object back = MessagePackSerializer.Deserialize(intKeyed, bytes, options)!;
        Assert.Equal(42, intKeyed.GetProperty("A")!.GetValue(back));
        Assert.Equal("hello", intKeyed.GetProperty("B")!.GetValue(back));
        Assert.Equal(2, Convert.ToInt32(intKeyed.GetProperty("E")!.GetValue(back)));
        object uBack = intKeyed.GetProperty("U")!.GetValue(back)!;
        Assert.Equal("UnionA", uBack.GetType().Name);
        Assert.Equal(7, uBack.GetType().GetProperty("V")!.GetValue(uBack));
        Assert.Equal(99, genInt.GetProperty("Value")!.GetValue(intKeyed.GetProperty("G")!.GetValue(back)));

        Type strKeyed = asm.GetType("Probe.StringKeyed", true)!;
        object s = Activator.CreateInstance(strKeyed)!;
        strKeyed.GetProperty("X")!.SetValue(s, 5);
        strKeyed.GetProperty("Y")!.SetValue(s, "y");
        byte[] sb = MessagePackSerializer.Serialize(strKeyed, s, options);
        Assert.Equal("{\"X\":5,\"Y\":\"y\"}", MessagePackSerializer.ConvertToJson(sb));
        object sBack = MessagePackSerializer.Deserialize(strKeyed, sb, options)!;
        Assert.Equal(5, strKeyed.GetProperty("X")!.GetValue(sBack));
        Assert.Equal("y", strKeyed.GetProperty("Y")!.GetValue(sBack));
    }
    finally
    {
        alc.Unload();
    }
}

