using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding1
{
    private const string TestSource = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver]
            partial class GeneratedMessagePackResolver
            {
            }
        }
        """;

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedTypesAreExcludedWhenConsumerTargetsSymbol(string symbol)
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "CountersignFinding1",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        var trees = driver.GetRunResult().GeneratedTrees;
        Assert.NotEmpty(trees);

        var opts = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: [symbol]);
        foreach (SyntaxTree tree in trees)
        {
            SyntaxNode root = CSharpSyntaxTree.ParseText(tree.GetText(), opts).GetRoot();
            var classes = root.DescendantNodes().OfType<ClassDeclarationSyntax>().ToList();
            Assert.NotEmpty(classes);
            bool anyExcluded = classes.Any(c => c.AttributeLists.SelectMany(a => a.Attributes).Any(a => a.Name.ToString().Contains("ExcludeFromCodeCoverage")));
            Assert.True(anyExcluded, $"With {symbol} defined, no active ExcludeFromCodeCoverage attribute in '{tree.FilePath}'.");
        }
    }

    [Fact]
    public async Task AttributeExistsInNetStandard20()
    {
        ImmutableArray<MetadataReference> refs = await ReferenceAssemblies.NetStandard.NetStandard20.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create("ns20", references: refs);
        Assert.NotNull(compilation.GetTypeByMetadataName("System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute"));
    }
}

