using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding2
{
    private const string Source = """
        using System.Diagnostics.CodeAnalysis;
        using MessagePack;
        using MessagePack.Resolvers;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        [GeneratedMessagePackResolver, ExcludeFromCodeCoverage]
        partial class MyGeneratedResolver { }

        [CompositeResolver(typeof(NativeGuidResolver)), ExcludeFromCodeCoverage]
        partial class MyCompositeResolver { }
        """;

    [Fact]
    public async Task UserAppliedExcludeFromCodeCoverageOnResolverStillCompiles()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "CountersignFinding2",
            syntaxTrees: [CSharpSyntaxTree.ParseText(Source, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        // Sanity: the user code alone compiles without CS0579.
        Assert.DoesNotContain(compilation.GetDiagnostics(), d => d.Id == "CS0579");

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator(), new CompositeResolverGenerator());
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);

        var dupes = output.GetDiagnostics().Where(d => d.Id == "CS0579").ToList();
        Assert.True(dupes.Count == 0, "Duplicate attribute errors after generation:\n" + string.Join("\n", dupes.Select(d => d.ToString())));
    }
}

