using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding3
{
    private const string Source = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver]
            partial class GeneratedMessagePackResolver
            {
                public static int UserWrittenHelper() => 42;
            }
        }
        """;

    [Fact]
    public async Task UserWrittenMemberOfPartialResolverIsNotExcludedFromCoverage()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "CountersignFinding3",
            syntaxTrees: [CSharpSyntaxTree.ParseText(Source, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);

        INamedTypeSymbol resolver = output.GetTypeByMetadataName("MessagePack.GeneratedMessagePackResolver")!;
        Assert.NotNull(resolver);
        IMethodSymbol helper = resolver.GetMembers("UserWrittenHelper").OfType<IMethodSymbol>().Single();

        // Coverage tools (coverlet, MS code coverage) exclude a member if it or any containing type carries the attribute.
        for (ISymbol? s = helper; s is not null and not INamespaceSymbol; s = s.ContainingSymbol)
        {
            Assert.DoesNotContain(
                s.GetAttributes(),
                a => a.AttributeClass?.ToDisplayString() == "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute");
        }
    }
}
